import { useEffect, useMemo, useRef, useState } from 'react';
import { executeAssistantStream } from '../lib/chatRunner';
import {
  loadActiveConversationId,
    loadConversations,
      loadProfile,
        loadTheme,
          saveActiveConversationId,
            saveConversations,
              saveProfile,
                saveTheme,
                } from '../lib/storage';
                import {
                  ASSISTANT_MODES,
                    type AssistantMode,
                      type Attachment,
                        type ChatMessage,
                          type Conversation,
                            type ThinkingDepth,
                              type UserProfile,
                              } from '../types/assistant';

                              export function useAssistantChat() {
                                const [conversations, setConversations] = useState<Conversation[]>(() => loadConversations());
                                  const [activeId, setActiveId] = useState<string | null>(() => {
                                      const savedId = loadActiveConversationId();
                                          const list = loadConversations();
                                              return savedId && list.some((c) => c.id === savedId) ? savedId : null;
                                                });
                                                  const [profile, setProfile] = useState<UserProfile>(() => loadProfile());
                                                    const [theme, setTheme] = useState<'light' | 'dark'>(() => loadTheme());
                                                      const [draftMode, setDraftMode] = useState<AssistantMode>('general');
                                                        const [thinkingDepth, setThinkingDepth] = useState<ThinkingDepth>('balanced');
                                                          const [input, setInput] = useState('');
                                                            const [attachments, setAttachments] = useState<Attachment[]>([]);
                                                              const [isStreaming, setIsStreaming] = useState(false);
                                                                const [streamingConvId, setStreamingConvId] = useState<string | null>(null);
                                                                  const abortControllerRef = useRef<AbortController | null>(null);

                                                                    const activeConversation = useMemo(
                                                                        () => conversations.find((c) => c.id === activeId) ?? null,
                                                                            [conversations, activeId],
                                                                              );
                                                                                const activeMode: AssistantMode = activeConversation?.mode ?? draftMode;
                                                                                  const activeModeMeta =
                                                                                      ASSISTANT_MODES.find((m) => m.id === activeMode) ?? ASSISTANT_MODES[0];

                                                                                        const lastModelMsgId = useMemo(() => {
                                                                                            if (!activeConversation) return null;
                                                                                                for (let i = activeConversation.messages.length - 1; i >= 0; i -= 1) {
                                                                                                      if (activeConversation.messages[i].role === 'model') {
                                                                                                              return activeConversation.messages[i].id;
                                                                                                                    }
                                                                                                                        }
                                                                                                                            return null;
                                                                                                                              }, [activeConversation]);

                                                                                                                                useEffect(() => {
                                                                                                                                    document.documentElement.classList.toggle('dark', theme === 'dark');
                                                                                                                                        saveTheme(theme);
                                                                                                                                          }, [theme]);

                                                                                                                                            useEffect(() => saveConversations(conversations), [conversations]);
                                                                                                                                              useEffect(() => saveActiveConversationId(activeId), [activeId]);
                                                                                                                                                useEffect(() => saveProfile(profile), [profile]);

                                                                                                                                                  const runResponse = async (
                                                                                                                                                      targetConvId: string,
                                                                                                                                                          historyForApi: ChatMessage[],
                                                                                                                                                              mode: AssistantMode,
                                                                                                                                                                  assistantMsgId: string,
                                                                                                                                                                      isFirstTurn: boolean,
                                                                                                                                                                          firstPromptText: string,
                                                                                                                                                                            ) => {
                                                                                                                                                                                const controller = new AbortController();
                                                                                                                                                                                    abortControllerRef.current = controller;
                                                                                                                                                                                        setIsStreaming(true);
                                                                                                                                                                                            setStreamingConvId(targetConvId);
                                                                                                                                                                                                try {
                                                                                                                                                                                                      await executeAssistantStream({
                                                                                                                                                                                                              targetConvId,
                                                                                                                                                                                                                      historyForApi,
                                                                                                                                                                                                                              mode,
                                                                                                                                                                                                                                      thinkingDepth,
                                                                                                                                                                                                                                              profile,
                                                                                                                                                                                                                                                      assistantMsgId,
                                                                                                                                                                                                                                                              isFirstTurn,
                                                                                                                                                                                                                                                                      firstPromptText,
                                                                                                                                                                                                                                                                              signal: controller.signal,
                                                                                                                                                                                                                                                                                      setConversations,
                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                } finally {
                                                                                                                                                                                                                                                                                                      setIsStreaming(false);
                                                                                                                                                                                                                                                                                                            setStreamingConvId(null);
                                                                                                                                                                                                                                                                                                                  abortControllerRef.current = null;
                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                          const handleSend = async (overridePrompt?: string) => {
                                                                                                                                                                                                                                                                                                                              if (isStreaming) return;
                                                                                                                                                                                                                                                                                                                                  const textToSend = (overridePrompt ?? input).trim();
                                                                                                                                                                                                                                                                                                                                      const currentAttachments = overridePrompt ? [] : attachments;
                                                                                                                                                                                                                                                                                                                                          if (!textToSend && currentAttachments.length === 0) return;

                                                                                                                                                                                                                                                                                                                                              const now = Date.now();
                                                                                                                                                                                                                                                                                                                                                  const userMsg: ChatMessage = {
                                                                                                                                                                                                                                                                                                                                                        id: crypto.randomUUID(),
                                                                                                                                                                                                                                                                                                                                                              role: 'user',
                                                                                                                                                                                                                                                                                                                                                                    content: textToSend,
                                                                                                                                                                                                                                                                                                                                                                          attachments: currentAttachments.length > 0 ? currentAttachments : undefined,
                                                                                                                                                                                                                                                                                                                                                                                createdAt: now,
                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                        const assistantMsgId = crypto.randomUUID();
                                                                                                                                                                                                                                                                                                                                                                                            const placeholder: ChatMessage = { id: assistantMsgId, role: 'model', content: '', createdAt: now + 1 };

                                                                                                                                                                                                                                                                                                                                                                                                if (!overridePrompt) {
                                                                                                                                                                                                                                                                                                                                                                                                      setInput('');
                                                                                                                                                                                                                                                                                                                                                                                                            setAttachments([]);
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                    if (!activeConversation) {
                                                                                                                                                                                                                                                                                                                                                                                                                          const newConvId = crypto.randomUUID();
                                                                                                                                                                                                                                                                                                                                                                                                                                const fallbackTitle =
                                                                                                                                                                                                                                                                                                                                                                                                                                        textToSend.slice(0, 42) + (textToSend.length > 42 ? '…' : '') ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                currentAttachments[0]?.name ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                        'New chat';
                                                                                                                                                                                                                                                                                                                                                                                                                                                              const newConv: Conversation = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id: newConvId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              title: fallbackTitle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      mode: draftMode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              messages: [userMsg, placeholder],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      createdAt: now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              updatedAt: now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setConversations((prev) => [newConv, ...prev]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setActiveId(newConvId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await runResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              newConvId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      [userMsg],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              draftMode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assistantMsgId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      textToSend || currentAttachments.map((a) => a.name).join(', '),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const targetConvId = activeConversation.id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const cleanPrior = activeConversation.messages.filter((m) => !m.isError);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setConversations((prev) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          prev.map((c) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    c.id === targetConvId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? { ...c, updatedAt: now, messages: [...c.messages, userMsg, placeholder] }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : c,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await runResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        targetConvId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                [...cleanPrior, userMsg],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        activeConversation.mode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assistantMsgId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cleanPrior.length === 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textToSend,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const handleRegenerate = async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!activeConversation || isStreaming) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const msgs = [...activeConversation.messages];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          while (msgs.length > 0 && msgs[msgs.length - 1].role === 'model') msgs.pop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (msgs.length === 0) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const assistantMsgId = crypto.randomUUID();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const placeholder: ChatMessage = { id: assistantMsgId, role: 'model', content: '', createdAt: Date.now() };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setConversations((prev) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                prev.map((c) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        c.id === activeConversation.id ? { ...c, updatedAt: Date.now(), messages: [...msgs, placeholder] } : c,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await runResponse(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            activeConversation.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  msgs.filter((m) => !m.isError),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        activeConversation.mode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assistantMsgId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      conversations,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          activeId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setActiveId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  activeConversation,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      activeMode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          activeModeMeta,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lastModelMsgId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  profile,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setProfile,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          theme,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              toggleTheme: () => setTheme((t) => (t === 'dark' ? 'light' : 'dark')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  thinkingDepth,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setThinkingDepth,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          input,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setInput,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  attachments,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setAttachments,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          isStreaming,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              streamingConvId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  handleNewChat: () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (isStreaming) abortControllerRef.current?.abort();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setActiveId(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setInput('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setAttachments([]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  handleDeleteConversation: (id: string) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (id === streamingConvId && isStreaming) abortControllerRef.current?.abort();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setConversations((prev) => prev.filter((c) => c.id !== id));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (activeId === id) setActiveId(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            handleTogglePin: (id: string) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setConversations((prev) => prev.map((c) => (c.id === id ? { ...c, pinned: !c.pinned } : c))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      handleRenameConversation: (id: string, title: string) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setConversations((prev) => prev.map((c) => (c.id === id ? { ...c, title } : c))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                handleModeChange: (mode: AssistantMode) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      activeConversation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? setConversations((prev) => prev.map((c) => (c.id === activeConversation.id ? { ...c, mode } : c)))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : setDraftMode(mode),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          handleSend,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              handleRegenerate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  handleStop: () => abortControllerRef.current?.abort(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }